<section class="panel"><h2>Inventory & borrowing reports</h2><p>Download CSV files for spreadsheets, or print this page to save a PDF. Teachers and staff can export their own borrowing records.</p><div class="actions"><a class="button" href="?page=reports&export=inventory">Download inventory CSV</a><a class="button" href="?page=reports&export=borrowing">Download borrowing CSV</a><button onclick="window.print()">Print report</button></div></section>
<section class="panel"><h2>Inventory summary by category</h2><table><tr><th>Category</th><th>Items</th><th>Available units</th><th>Low-stock items</th></tr><?php foreach(query('SELECT c.name,COUNT(i.id) items,COALESCE(SUM(i.quantity),0) units,COALESCE(SUM(i.quantity<=i.low_stock),0) low FROM categories c LEFT JOIN items i ON i.category_id=c.id GROUP BY c.id,c.name ORDER BY c.name')->fetchAll() as $r): ?><tr><td><?= e($r['name']) ?></td><td><?= e($r['items']) ?></td><td><?= e($r['units']) ?></td><td><?= e($r['low']) ?></td></tr><?php endforeach ?></table></section>
